import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";var i=JSON.parse(`{"title":"Shared tooling and configuration","description":"","frontmatter":{},"headers":[],"relativePath":"shared-tooling.md","filePath":"shared-tooling.md"}`),a={name:`shared-tooling.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="shared-tooling-and-configuration" tabindex="-1">Shared tooling and configuration <a class="header-anchor" href="#shared-tooling-and-configuration" aria-label="Permalink to “Shared tooling and configuration”">​</a></h1><h2 id="what-is-centralized-at-the-repository-root" tabindex="-1">What is centralized at the repository root <a class="header-anchor" href="#what-is-centralized-at-the-repository-root" aria-label="Permalink to “What is centralized at the repository root”">​</a></h2><p>These files intentionally live once at the <strong>monorepo root</strong> and apply to all (or most) packages:</p><table tabindex="0"><thead><tr><th>Area</th><th>Examples</th></tr></thead><tbody><tr><td><strong>JavaScript / Node</strong></td><td>Root <code>package.json</code> scripts, <code>pnpm-workspace.yaml</code>, shared <code>typescript</code> / <code>@wordpress/scripts</code> versions</td></tr><tr><td><strong>Linting</strong></td><td><code>eslint.config.js</code>, <code>.stylelintrc</code>, <code>.prettierrc.js</code>, markdown lint config, <code>phpcs.xml</code> via Composer at root</td></tr><tr><td><strong>Testing</strong></td><td>Shared Playwright setup under <code>packages/e2e/</code>, PHPUnit XML in <code>packages/phpunit-config/</code></td></tr><tr><td><strong>Git</strong></td><td>Root <code>.gitignore</code>; release export rules often use <code>.gitattributes</code> per package</td></tr></tbody></table><p>Run <strong>monorepo-wide</strong> checks from the root, for example:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">          # JS, CSS, PHP, MD, package.json (see root package.json)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">         # all projects with a build target</span></span></code></pre></div><h2 id="release-packaging-with-gitattributes" tabindex="-1">Release packaging with <code>.gitattributes</code> <a class="header-anchor" href="#release-packaging-with-gitattributes" aria-label="Permalink to “Release packaging with .gitattributes”">​</a></h2><p>Release zips for plugins and themes are built with <code>git archive</code>. Any path marked <code>export-ignore</code> in a package&#39;s <code>.gitattributes</code> is left out of the zip, so these lines decide what ships to production.</p><p>Every plugin and theme must contain this standard list (it currently only excludes paths; no line-ending or language rules):</p><div class="language-gitattributes"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">gitattributes</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.gitattributes                  export-ignore</span></span>
<span class="line"><span>.gitignore                      export-ignore</span></span>
<span class="line"><span>.gitkeep                        export-ignore</span></span>
<span class="line"><span>.wp-env.json                    export-ignore</span></span>
<span class="line"><span>.eslintignore                   export-ignore</span></span>
<span class="line"><span>.eslintrc.js                    export-ignore</span></span>
<span class="line"><span>eslint.config.js                export-ignore</span></span>
<span class="line"><span>.markdownlint.json              export-ignore</span></span>
<span class="line"><span>.markdownlintignore             export-ignore</span></span>
<span class="line"><span>.npmrc                          export-ignore</span></span>
<span class="line"><span>CHANGELOG.md                    export-ignore</span></span>
<span class="line"><span>CODEOWNERS                      export-ignore</span></span>
<span class="line"><span>checklist.md                    export-ignore</span></span>
<span class="line"><span>jest.config.js                  export-ignore</span></span>
<span class="line"><span>phpunit.xml                     export-ignore</span></span>
<span class="line"><span>playwright.config.js            export-ignore</span></span>
<span class="line"><span>playwright.regression.config.js export-ignore</span></span>
<span class="line"><span>package-lock.json               export-ignore</span></span>
<span class="line"><span>package.json                    export-ignore</span></span>
<span class="line"><span>README.md                       export-ignore</span></span>
<span class="line"><span>docs                            export-ignore</span></span>
<span class="line"><span>documentation                   export-ignore</span></span>
<span class="line"><span>scripts                         export-ignore</span></span>
<span class="line"><span>tests                           export-ignore</span></span>
<span class="line"><span>.editorconfig                    export-ignore</span></span>
<span class="line"><span>.github                          export-ignore</span></span>
<span class="line"><span>.distignore                      export-ignore</span></span>
<span class="line"><span>.husky                           export-ignore</span></span>
<span class="line"><span>.vscode                          export-ignore</span></span>
<span class="line"><span>phpcs.xml                        export-ignore</span></span>
<span class="line"><span>phpcs.xml.dist                   export-ignore</span></span>
<span class="line"><span>phpstan.neon                     export-ignore</span></span>
<span class="line"><span>phpstan.neon.dist                export-ignore</span></span>
<span class="line"><span>tsconfig.json                    export-ignore</span></span>
<span class="line"><span>project.json                     export-ignore</span></span>
<span class="line"><span>webpack.config.js                export-ignore</span></span>
<span class="line"><span>eslint.json                      export-ignore</span></span></code></pre></div><p>The release zip (<code>.github/scripts/prepare-release-zip.sh</code>) is <code>git archive HEAD</code> of the product folder plus the built <code>dist/</code>. <code>vendor/</code> is not shipped. <code>src/</code> is not excluded because it can hold runtime PHP.</p><p>Rules for files a product does not have are harmless, so the list is shared as-is.</p><ul><li><p><strong>Kept in the zip:</strong> <code>composer.json</code> and <code>composer.lock</code>. Composer sites install from <code>packages.json</code>, which is built from the repository <code>composer.json</code> at release time. Keeping both files lets a site that deploys the zip without Composer run <code>composer install --no-dev</code> inside the product folder and get the locked dependencies.</p></li><li><p><strong>Excluded:</strong> <code>phpcs.xml</code> and <code>project.json</code>. <code>phpcs.xml</code> is lint configuration, and <code>project.json</code> is Nx configuration that the release workflow reads from the repository, not from the zip. Neither is used at runtime.</p></li><li><p><strong>Source of truth:</strong> <code>tools/monorepo/src/generators/plugin/files/.gitattributes</code>. The theme generator copy is identical, so new products inherit the standard.</p></li><li><p><strong>Enforcement:</strong> <code>pnpm lint-gitattributes</code> (<code>tools/check-gitattributes.mjs</code>) runs in the PR workflow and fails if a plugin, theme, or generator copy is missing a standard rule.</p></li><li><p><strong>Extra rules:</strong> products may add lines for product-specific files, but should not remove standard ones. If many products need the same extra line, propose adding it to the standard.</p></li></ul><h2 id="what-stays-package-specific" tabindex="-1">What stays package-specific <a class="header-anchor" href="#what-stays-package-specific" aria-label="Permalink to “What stays package-specific”">​</a></h2><p>Keep configuration <strong>in the package</strong> when it encodes product behavior:</p><ul><li><strong><code>block.json</code></strong>, theme <code>theme.json</code>, WordPress templates, and PHP bootstrap files</li><li><strong><code>.wp-env.json</code></strong> — port mappings, plugin/theme mappings, and env-specific options</li><li><strong><code>composer.json</code></strong> — package name, autoload namespaces, <code>require</code> / <code>require-dev</code> for that product</li><li><strong><code>project.json</code></strong> — which Nx targets the package implements and <code>implicitDependencies</code></li><li><strong>Playwright specs</strong> under <code>tests/e2e/</code>, <code>tests/accessibility/</code>, and <code>tests/screenshot/</code> (generator conventions)</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><h3 id="linting" tabindex="-1">Linting <a class="header-anchor" href="#linting" aria-label="Permalink to “Linting”">​</a></h3><ul><li><strong>JavaScript:</strong> <code>pnpm lint-js</code> uses the ESLint version installed for <code>@wordpress/scripts</code> with root <code>eslint.config.js</code>; fix with <code>pnpm fix-js</code>.</li><li><strong>CSS/SCSS:</strong> <code>pnpm lint-css</code> → <code>wp-scripts lint-style</code>; fix with <code>pnpm fix-css</code>.</li><li><strong>PHP:</strong> <code>pnpm lint-php</code> → root Composer <code>lint-php</code> (PHPCS); fix with <code>pnpm fix-php</code>.</li><li><strong>Markdown:</strong> <code>pnpm lint-md</code> for docs; <code>pnpm fix-md</code> for autofix.</li></ul><h3 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to “Testing”">​</a></h3><ul><li><strong>Playwright configuration:</strong> <code>packages/e2e/playwright.config.js</code> defines the <code>e2e</code>, <code>accessibility</code>, and <code>screenshot</code> projects. Each plugin/theme <code>playwright.config.js</code> reuses this shared configuration; put specs in the matching <code>tests/</code> subdirectory.</li><li><strong>E2E:</strong> <code>npx nx run &lt;project&gt;:test-e2e</code> runs the <code>e2e</code> project; <code>npx nx run &lt;project&gt;:test-e2e-docker</code> runs it in the Playwright container. Both depend on <code>wp-env-start</code> and upstream <code>build</code> per <code>nx.json</code>.</li><li><strong>Accessibility:</strong> <code>npx nx run &lt;project&gt;:test-accessibility</code> runs the <code>accessibility</code> project.</li><li><strong>Screenshot regression:</strong> <code>npx nx run &lt;project&gt;:test-screenshot</code> compares against committed screenshots; <code>npx nx run &lt;project&gt;:test-screenshot-generate</code> regenerates them.</li><li><strong>PHP integration:</strong> <code>npx nx run &lt;project&gt;:test-integration</code> runs PHPUnit inside <code>wp-env</code> using shared config from <code>packages/phpunit-config</code>.</li></ul><h3 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to “Build”">​</a></h3><ul><li><strong>Production assets:</strong> <code>npx nx run &lt;project&gt;:build</code> → <code>wp-scripts build</code>, output typically <code>dist/</code>.</li></ul><p>The root flat config preserves the WordPress recommended rules and BCEW&#39;s custom overrides. <code>@wordpress/scripts</code> 31.8&#39;s <code>lint-js</code> wrapper adds legacy CLI flags that ESLint 8 rejects in flat-config mode, so <code>tools/lint-js.js</code> invokes the same ESLint 8.57 binary directly and enables flat config. The flat config also retains the build, <code>node_modules</code>, and vendor ignores formerly supplied by <code>@wordpress/scripts</code>. <code>FlatCompat</code> adapts the WordPress shareable config, which is still in the legacy format; this compatibility layer can be removed when the WordPress tooling provides a native flat config. Under this compatibility setup, <code>jsdoc/no-undefined-types</code> reports imported TypeScript types as undefined even though the legacy config accepts them, so the rule remains enabled for JavaScript and is disabled for TypeScript to preserve existing lint results.</p><h2 id="migration-expectation-remove-redundant-configuration" tabindex="-1">Migration expectation: remove redundant configuration <a class="header-anchor" href="#migration-expectation-remove-redundant-configuration" aria-label="Permalink to “Migration expectation: remove redundant configuration”">​</a></h2><p>When importing a standalone repository:</p><ul><li>Delete duplicate lint configs, per-repo GitHub Actions, and redundant Prettier/Stylelint files <strong>unless</strong> the monorepo root cannot express a needed exception.</li><li>If a one-off rule is required, prefer the <strong>smallest local override</strong> documented in a comment or package readme rather than forking entire configs.</li></ul><h2 id="documentation-site-tooling" tabindex="-1">Documentation site tooling <a class="header-anchor" href="#documentation-site-tooling" aria-label="Permalink to “Documentation site tooling”">​</a></h2><p>The docs portal uses <strong>VitePress</strong> and a sync script (<code>tools/sync-docs.mjs</code>). Package docs remain in <code>plugins/&lt;slug&gt;/docs/</code> and <code>themes/&lt;slug&gt;/docs/</code>. See <a href="./documentation-site">Documentation site</a>.</p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};